function c_next(page, url) {
  const n_u = [];
  for (let num = 1; num <= page; num++) {
    n_u.push(`${url}_${num}.html`);
  }
  return n_u;
}

let burl = chapter.url;
let content = java.ajax(burl);
let text = java.getString("article.font_max@html", content);
//java.log(text)
let regex = /第\((\d+)\/(\d+)\)页/;
let p_g = text.match(regex)[2];
let url = burl.split(".html")[0];
let next_url;
if ( p_g[2] == "1") {
	  next_url = "";
} else {
	  next_url = c_next(p_g, url).join("\n");
}

